import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";

export default function Candidates() {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await api.get("/candidates");
        setCandidates(res.data);
      } catch (err) {
        setError(err.response?.data?.error || "Failed to load candidates");
      } finally {
        setLoading(false);
      }
    };
    fetchCandidates();
  }, []);

  if (loading)
    return <p className="text-center mt-10 text-gray-600">Loading candidates...</p>;
  if (error) return <p className="text-center mt-10 text-red-600">{error}</p>;

  return (
    <div className="min-h-screen bg-gray-100 px-8 py-12">
      {/* Page header */}
      <div className="max-w-7xl mx-auto mb-10">
        <h1 className="text-4xl font-bold text-gray-800">Election Candidates</h1>
        <p className="text-gray-600 mt-2 text-lg">
          Review the list of approved candidates and cast your vote securely.
        </p>
      </div>

      {/* Candidate cards */}
      <div className="max-w-7xl mx-auto grid gap-8 sm:grid-cols-2 lg:grid-cols-3">
        {candidates.map((c) => (
          <div
            key={c.id}
            className="bg-white rounded-2xl shadow-lg border border-gray-200 p-6 flex flex-col hover:shadow-xl transition"
          >
            {/* Candidate header */}
            <div className="flex items-center gap-4 mb-4">
              <div className="w-14 h-14 flex items-center justify-center rounded-full bg-blue-600 text-white text-lg font-bold shadow-md">
                {c.name.charAt(0)}
              </div>
              <div>
                <h2 className="text-xl font-semibold text-gray-800">{c.name}</h2>
                <p className="text-gray-500 text-sm">{c.position}</p>
              </div>
            </div>

            {/* Candidate body (optional manifesto) */}
            {c.manifesto && (
              <p className="text-gray-600 text-sm flex-grow line-clamp-3 mb-4">
                {c.manifesto}
              </p>
            )}

            {/* Action */}
            <button
              onClick={() => navigate("/vote", { state: { candidate: c } })}
              className="mt-auto bg-blue-600 text-white px-5 py-2 rounded-xl hover:bg-blue-700 transition font-medium w-full"
            >
              Vote
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
